export const extraLessons=[
 {id:'energy',grade:10,title:'Năng lượng cho một tế bào',kicker:'CHUYỂN HÓA NĂNG LƯỢNG',description:'Gặp ATP và enzyme — những mắt xích giúp tế bào duy trì hoạt động.',type:'Khám phá & thí nghiệm',icon:'flask',minutes:8,visual:'energy',lab:'enzyme',question:'Enzyme thường thúc đẩy phản ứng bằng cách nào?',answers:['Hạ năng lượng hoạt hóa','Tạo năng lượng từ hư không','Bị tiêu hao hoàn toàn sau phản ứng'],correct:0,explanation:'Enzyme là chất xúc tác sinh học: làm giảm năng lượng hoạt hóa và không bị tiêu hao theo phản ứng mà nó xúc tác.',intro:'Tế bào liên tục biến đổi chất và năng lượng. ATP tham gia ghép nối các quá trình, còn enzyme giúp nhiều phản ứng diễn ra hiệu quả.',heading:'Phản ứng nhanh hơn, vẫn tuân theo quy luật năng lượng',points:['Năng lượng không tự sinh ra. Tế bào chuyển đổi năng lượng giữa các dạng trong quá trình sống.','ATP có thể cung cấp năng lượng cho nhiều hoạt động thông qua sự ghép nối phản ứng.','Hoạt tính enzyme phụ thuộc cấu trúc và môi trường. Nhiệt độ, pH không phù hợp có thể làm hoạt tính giảm.'],wonder:'Không có một nhiệt độ tối ưu chung cho tất cả enzyme. Mỗi loại có đặc điểm riêng.',source:'https://openstax.org/books/biology-2e/pages/6-5-enzymes'},
 {id:'division',grade:10,title:'Từ một tế bào đến hai',kicker:'CHU KÌ TẾ BÀO & PHÂN BÀO',description:'Thông tin được sao chép và phân chia ra sao khi tế bào tạo thế hệ mới?',type:'Bài học khám phá',icon:'layers',minutes:8,visual:'cell',question:'Trong chu kì tế bào nhân thực điển hình, ADN được nhân đôi chủ yếu ở pha nào?',answers:['Pha G₁','Pha S','Pha G₂'],correct:1,explanation:'ADN được nhân đôi trong pha S của kì trung gian, chuẩn bị cho sự phân chia vật chất di truyền.',intro:'Sinh trưởng và thay thế tế bào cần một quá trình phân chia được điều hòa chặt chẽ. Vật chất di truyền phải được sao chép trước khi phân chia.',heading:'Chuẩn bị trước khi tách đôi',points:['Kì trung gian gồm các pha G₁, S và G₂ trong mô hình chu kì tế bào điển hình.','Nguyên phân phân chia nhân, phối hợp với phân chia tế bào chất để hình thành tế bào con.','Giảm phân có vai trò khác với nguyên phân: góp phần tạo tế bào mang bộ nhiễm sắc thể giảm đi một nửa trong chu kì sinh sản hữu tính.'],wonder:'Không phải tế bào nào cũng tiếp tục phân chia. Nhiều tế bào đi vào trạng thái không phân chia trong thời gian dài.',source:'https://openstax.org/books/biology-2e/pages/10-2-the-cell-cycle'},
 {id:'microbes',grade:10,title:'Những cư dân mắt thường không thấy',kicker:'VI SINH VẬT & ỨNG DỤNG',description:'Sự sống nhỏ bé góp phần vào lên men, phân giải và các chu trình tự nhiên.',type:'Bài học khám phá',icon:'microscope',minutes:7,visual:'water',question:'Nhận định nào phù hợp về vi sinh vật?',answers:['Tất cả đều gây bệnh','Chỉ sống trong cơ thể người','Có nhiều nhóm và nhiều vai trò khác nhau'],correct:2,explanation:'Vi sinh vật rất đa dạng. Nhiều nhóm có ích cho hệ sinh thái và được ứng dụng trong sản xuất, bên cạnh các nhóm có thể gây bệnh.',intro:'“Vi sinh vật” mô tả các sinh vật có kích thước nhỏ cần công cụ phù hợp để quan sát, không phải tên của một nhóm phân loại duy nhất.',heading:'Nhỏ bé, vai trò không nhỏ',points:['Các vi sinh vật có nhiều kiểu dinh dưỡng và có thể sống trong nhiều môi trường.','Nhiều nhóm tham gia phân giải, tái sử dụng vật chất hoặc sống cộng sinh.','Con người khai thác hoạt động vi sinh vật trong các quá trình như lên men; từng ứng dụng cần điều kiện và quy trình riêng.'],wonder:'Không nên kết luận một vi sinh vật có hại hay có ích chỉ dựa vào kích thước hoặc vẻ ngoài.',source:'https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/sgv-sinh-hoc.4492270850'},
 {id:'growth',grade:11,title:'Một mầm xanh lớn lên',kicker:'SINH TRƯỞNG & PHÁT TRIỂN',description:'Lớn lên về kích thước khác gì với thay đổi về cấu trúc và chức năng?',type:'Bài học khám phá',icon:'sprout',minutes:7,image:'ecosystem.jpg',visual:'leaf',question:'Ví dụ nào thể hiện sự phát triển ở thực vật rõ hơn việc chỉ tăng kích thước?',answers:['Cây chuyển sang hình thành hoa','Thân cây dài thêm 1 cm','Khối lượng cây tăng'],correct:0,explanation:'Hình thành hoa thể hiện sự thay đổi về tổ chức và giai đoạn sống. Sinh trưởng nhấn mạnh sự tăng kích thước hoặc khối lượng.',intro:'Từ hạt nảy mầm đến cây ra hoa, sinh vật vừa tăng về lượng vừa có những biến đổi về chất.',heading:'Hai quá trình gắn bó với nhau',points:['Sinh trưởng là sự tăng kích thước, khối lượng của cơ thể hoặc bộ phận.','Phát triển bao gồm những biến đổi về tổ chức và chức năng trong vòng đời.','Gene, hormone và điều kiện môi trường cùng ảnh hưởng đến sinh trưởng và phát triển.'],wonder:'Hai cây cùng tuổi có thể có kích thước và giai đoạn phát triển khác nhau khi điều kiện sống khác nhau.',source:'https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/shs-sinh-hoc.4492265451'},
 {id:'responses',grade:11,title:'Vì sao cây nghiêng về cửa sổ?',kicker:'CẢM ỨNG Ở SINH VẬT',description:'Thay đổi hướng chiếu sáng và quan sát phản ứng của chồi non.',type:'Khám phá & thí nghiệm',icon:'sun',minutes:8,visual:'mendel',lab:'phototropism',question:'Chồi non cong về phía nguồn sáng là ví dụ của hiện tượng nào?',answers:['Hướng sáng dương','Thoát hơi nước','Phân li allele'],correct:0,explanation:'Hướng sáng dương là phản ứng sinh trưởng hướng về phía nguồn sáng. Nó không phải chuyển động tức thời của cả cây.',intro:'Sinh vật tiếp nhận thông tin từ môi trường và có phản ứng. Ở chồi non, ánh sáng một phía có thể tạo nên sinh trưởng không đều.',heading:'Một phản ứng cần thời gian',points:['Hướng động là phản ứng sinh trưởng có hướng phụ thuộc vào tác nhân kích thích.','Trong ví dụ chồi non, sinh trưởng không đều ở hai phía góp phần tạo nên độ cong.','Phân bố và tác động của auxin liên quan đến phản ứng này; đáp ứng còn phụ thuộc loài và điều kiện.'],wonder:'Chuyển hướng nguồn sáng không làm thân cây trưởng thành lập tức quay lại. Mô hình cần thể hiện tiến trình sinh trưởng.',source:'https://openstax.org/books/biology-2e/pages/30-6-plant-sensory-systems-and-responses'},
 {id:'reproduction',grade:11,title:'Sự sống nối tiếp sự sống',kicker:'SINH SẢN Ở SINH VẬT',description:'So sánh sinh sản vô tính, hữu tính và ý nghĩa của chúng trong vòng đời.',type:'Bài học khám phá',icon:'leaf',minutes:8,visual:'mendel',question:'Đặc điểm cốt lõi của sinh sản hữu tính là gì?',answers:['Luôn cần hai cơ thể bố mẹ khác nhau','Có sự hợp nhất giao tử','Không có biến dị tổ hợp'],correct:1,explanation:'Sinh sản hữu tính có sự hợp nhất giao tử. Một số sinh vật có thể tự thụ tinh, nên không thể khẳng định luôn cần hai cơ thể khác nhau.',intro:'Các cơ chế sinh sản giúp duy trì dòng sống, nhưng cách hình thành cá thể mới và nguồn biến dị không giống nhau.',heading:'Nhiều con đường tạo thế hệ mới',points:['Sinh sản vô tính không có sự hợp nhất giao tử; thường tạo hậu thế gần giống nguồn ban đầu về di truyền, trừ biến đổi phát sinh.','Sinh sản hữu tính kết hợp quá trình tạo giao tử và thụ tinh, có thể tạo biến dị tổ hợp.','Ở thực vật có hoa, cần phân biệt thụ phấn với thụ tinh: phấn đến vị trí phù hợp chưa đồng nghĩa giao tử đã hợp nhất.'],wonder:'Giâm cành là một ứng dụng sinh sản sinh dưỡng. Gieo hạt và giâm cành không truyền đạt đặc điểm theo cùng một cách.',source:'https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/shs-sinh-hoc.4492265451'},
 {id:'evolution',grade:12,title:'Quần thể thay đổi qua thế hệ',kicker:'TIẾN HÓA',description:'Theo dấu biến dị di truyền và cách quần thể thay đổi theo thời gian.',type:'Bài học khám phá',icon:'route',minutes:8,image:'forest.jpg',visual:'leaf',question:'Trong tiến hóa nhỏ, đại lượng nào của quần thể có thể thay đổi qua các thế hệ?',answers:['Tần số allele','Mọi cá thể đồng loạt tự đổi gene vì cần','Chỉ tuổi của một cá thể'],correct:0,explanation:'Tiến hóa nhỏ liên quan đến thay đổi tần số allele và thành phần kiểu gene của quần thể qua các thế hệ.',intro:'Một cá thể có thể lớn lên hoặc thích nghi sinh lí trong đời sống. Điều đó khác với biến đổi di truyền của quần thể qua thế hệ.',heading:'Nhìn ở cấp quần thể',points:['Biến dị di truyền cung cấp nguyên liệu cho các quá trình tiến hóa.','Chọn lọc tự nhiên liên quan đến khác biệt về khả năng sống sót và đóng góp hậu thế trong môi trường cụ thể.','Đột biến, di nhập gene và các yếu tố ngẫu nhiên cũng có thể làm thay đổi thành phần di truyền.'],wonder:'Chọn lọc tự nhiên không có mục tiêu định trước và không tạo ra biến dị chỉ vì sinh vật “cần” nó.',source:'https://openstax.org/books/biology-2e/pages/19-1-population-evolution'},
 {id:'ecology',grade:12,title:'Năng lượng đi đâu trong khu rừng?',kicker:'SINH THÁI HỌC',description:'Dựng tháp năng lượng và xem điều gì thay đổi qua các bậc dinh dưỡng.',type:'Khám phá & thí nghiệm',icon:'chart',minutes:9,image:'ecosystem.jpg',visual:'leaf',lab:'ecosystem',question:'Vì sao năng lượng có sẵn thường giảm khi đi lên các bậc dinh dưỡng?',answers:['Năng lượng biến mất hoàn toàn khỏi tự nhiên','Một phần được sử dụng và tỏa nhiệt, không chuyển hết sang bậc sau','Mọi sinh vật đều ngừng hô hấp'],correct:1,explanation:'Năng lượng được sử dụng cho hoạt động sống, tỏa nhiệt hoặc nằm trong phần không được sinh vật bậc sau ăn và đồng hóa.',intro:'Hệ sinh thái gồm quần xã và môi trường, được kết nối bởi trao đổi vật chất và dòng năng lượng.',heading:'Vật chất tuần hoàn, năng lượng có dòng đi',points:['Sinh vật sản xuất đưa năng lượng vào lưới thức ăn, thường thông qua quang hợp.','Năng lượng truyền qua các quan hệ dinh dưỡng với hiệu suất thay đổi; không có một tỉ lệ đúng cho mọi hệ.','Mô hình chuỗi thức ăn đơn giản giúp so sánh, nhưng lưới thức ăn thực tế có nhiều nhánh và sinh vật phân giải.'],wonder:'Tháp năng lượng luôn giảm theo bậc khi xét cùng diện tích và khoảng thời gian; không nên nhầm với tháp số lượng.',source:'https://openstax.org/books/biology-2e/pages/46-2-energy-flow-through-ecosystems'},
 {id:'human-genetics',grade:12,title:'Di truyền học đi vào đời sống',kicker:'DI TRUYỀN HỌC NGƯỜI & ỨNG DỤNG',description:'Đọc một sơ đồ phả hệ giả định và nhận biết điều mô hình có thể, chưa thể nói.',type:'Bài học khám phá',icon:'dna',minutes:8,visual:'dna',question:'Khi đọc phả hệ của một tính trạng, điều nào cần được cân nhắc?',answers:['Chỉ cần biết màu biểu tượng là đủ kết luận mọi bệnh','Giả định di truyền, dữ liệu và ảnh hưởng của môi trường','Một gene luôn quyết định mọi đặc điểm'],correct:1,explanation:'Suy luận từ phả hệ cần dữ liệu và giả định phù hợp. Nhiều tính trạng có cơ sở đa gene hoặc chịu ảnh hưởng môi trường.',intro:'Di truyền học giúp nghiên cứu cách đặc điểm được truyền đạt và hỗ trợ các ứng dụng, nhưng không phải mọi đặc điểm đều tuân theo một phép lai đơn giản.',heading:'Hiểu mô hình trước khi suy luận',points:['Phả hệ dùng kí hiệu và quan hệ thế hệ để tổ chức thông tin về một tính trạng.','Mô hình một gene có thể dùng để học quy luật, nhưng không đại diện cho mọi đặc điểm ở người.','Công nghệ gene và nghiên cứu hệ gene có nhiều ứng dụng; việc dùng dữ liệu di truyền cần tôn trọng quyền riêng tư và bối cảnh.'],wonder:'Phòng thí nghiệm Mendel của VNScape dùng cây đậu giả định, không dùng để dự đoán sức khỏe của một gia đình.',source:'https://sachdientu.nxbgd.vn/thu-vien-so/doc-sach/sgv-sinh-hoc.4496239849'}
];
